"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[13293],{28453:(e,t,a)=>{a.d(t,{R:()=>s,x:()=>r});var n=a(96540);const o={},i=n.createContext(o);function s(e){const t=n.useContext(i);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),n.createElement(i.Provider,{value:t},e.children)}},96169:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>c,contentTitle:()=>r,default:()=>d,frontMatter:()=>s,metadata:()=>n,toc:()=>h});const n=JSON.parse('{"id":"qiangguo/goodcat","title":"","description":"Stated more bluntly, this saying means that catching mice is the sole criterion for being a good cat. However, just as some cats are prodigies that can chase mice all over the street before they\'re even as big as a mouse, yet once you bring them home and pamper them to full size, they become useless; some cats are only effective in their own little corner -- not just mice, but field mice and squirrels too, anything remotely related to mice is doomed, but take them out of their corner and they\'re useless again; some cats\' relationship with mice may even depend on the weather -- when the moon is full they get fierce with mice, but when the moon wanes they wane too. Does there exist a super-cat that can catch mice at any time, any place, under any circumstances? If not, then what exactly is the standard for \\"catching mice\\"? Under this standard, is there only one cat that qualifies? If many cats qualify -- all good cats -- but in practice you can\'t keep them all and must choose, you\'ll need new criteria.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/goodcat.md","sourceDirName":"qiangguo","slug":"/qiangguo/goodcat","permalink":"/qiangguo/goodcat","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"goodcat","title":"","hide_table_of_contents":true},"sidebar":"qiangguoSidebar","previous":{"title":"\u4e00\u53e5\u6df7\u8bdd\uff1a\u201c\u4e0d\u7ba1\u767d\u732b\u3001\u9ed1\u732b\uff0c\u6293\u5230\u8001\u9f20\u7684\u5c31\u662f\u597d\u732b\u201d","permalink":"/qiangguo/adamnword"},"next":{"title":"\u674e\u9e3f\u7ae0\u5148\u751f\u4e0d\u6127\u201c\u4e2d\u56fd\u7b2c\u4e00\u63a8\u9500\u5458\u201d  \u4e3a\u674e\u9e3f\u7ae0\u5148\u751f\u5728\u300a\u8d70\u5411\u5171\u548c\u300b\u4e2d\u8d70\u5411\u5e73\u53cd\u800c\u4f5c","permalink":"/qiangguo/china1stsalesman"}}');var o=a(74848),i=a(28453);const s={id:"goodcat",title:"",hide_table_of_contents:!0},r="An Analysis of \"It Doesn't Matter Whether the Cat Is Black or White, as Long as It Catches Mice It's a Good Cat\"",c={},h=[];function l(e){const t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"an-analysis-of-it-doesnt-matter-whether-the-cat-is-black-or-white-as-long-as-it-catches-mice-its-a-good-cat",children:"An Analysis of \"It Doesn't Matter Whether the Cat Is Black or White, as Long as It Catches Mice It's a Good Cat\""})}),"\n",(0,o.jsx)(t.p,{children:"Stated more bluntly, this saying means that catching mice is the sole criterion for being a good cat. However, just as some cats are prodigies that can chase mice all over the street before they're even as big as a mouse, yet once you bring them home and pamper them to full size, they become useless; some cats are only effective in their own little corner -- not just mice, but field mice and squirrels too, anything remotely related to mice is doomed, but take them out of their corner and they're useless again; some cats' relationship with mice may even depend on the weather -- when the moon is full they get fierce with mice, but when the moon wanes they wane too. Does there exist a super-cat that can catch mice at any time, any place, under any circumstances? If not, then what exactly is the standard for \"catching mice\"? Under this standard, is there only one cat that qualifies? If many cats qualify -- all good cats -- but in practice you can't keep them all and must choose, you'll need new criteria."}),"\n",(0,o.jsx)(t.p,{children:"For example, if two cats can both catch mice -- one black, one white -- and you can only choose one, when you can't have both, with only one choice to make, which is it -- black or white? In this situation, not arguing actually becomes the precondition for arguing. Those who prefer white will say the black one only caught small mice in the past, was cruel, not environmentally friendly, and unsustainable; those who prefer black will say the white one just tosses mice aside after catching them, then sneaks off to steal fish and flirts with the neighbor's cat -- treacherous through and through. The real-world quarreling will inevitably be endless. Furthermore, once this criterion becomes the sole standard for judging whether a cat is good or bad, in order to become a good cat, an infinite variety of tricks will be invented around this single standard. These tricks will quickly render the standard ambiguous, until ultimately there is effectively no standard at all."}),"\n",(0,o.jsx)(t.p,{children:"More importantly, if you already have one at home -- say, a black cat -- people always think the neighbor's food tastes better. Especially after getting used to the black cat, one glance at the neighbor's white cat brings a sense of novelty. If the neighbor happens to be an extraordinary braggart, claiming their cat catches one thousand several hundred mice a day, even insinuating that your black cat actually swiped its catches from their mouse pile, what do you do? Option One: out-brag them. Option Two: clone their cat. Option Three: go home and paint the black cat with lime. Of course, there are other options not mentioned here."}),"\n",(0,o.jsx)(t.p,{children:'In short, whether catching mice can be indiscriminately associated with "good cat" in a necessary correspondence -- this question is absolutely not as simple as it sounds. And whether the time has now come when we must distinguish between black and white is probably also a question that can no longer be avoided.'})]})}function d(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}}}]);